                      child: _buildInputField(
                        label: 'الاسم الكامل',
                        hint: 'الاسم',
                        controller: _fullNameController,
                      ),
                    ),

                    // Field 3: Phone
                    Positioned(
                      left: 53,
                      top: 285,
                      child: _buildInputField(
                        label: 'رقم الجوال',
                        hint: '05XXXXXXXX',
                        controller: _phoneController,
                        keyboardType: TextInputType.phone,
                      ),
                    ),

                    // Field 4: CR Number
                    Positioned(
                      left: 53,
                      top: 380,
                      child: _buildInputField(
                        label: 'السجل التجاري',
                        hint: '10XXXXXXXX',
                        controller: _crController,
                        keyboardType: TextInputType.number,
                      ),
                    ),

                    // Field 5: Password
                    Positioned(
                      left: 53,
                      top: 475,
                      child: _buildInputField(
                        label: 'كلمة المرور',
                        hint: '••••••••',
                        controller: _passwordController,
                        isPassword: true,
                      ),
                    ),

                    // Create Account Button
                    Positioned(
                      left: 51,
                      top: 580,
                      child: GestureDetector(
                        onTap: _loading ? null : _register,
                        child: Container(
                          width: 300,
                          height: 52,
                          decoration: ShapeDecoration(
                            color: const Color(0xFF0B7856),
                            shape: RoundedRectangleBorder(
                              borderRadius: BorderRadius.circular(16),
                            ),
                          ),
                          alignment: Alignment.center,
                          child: const Text(
                            'انشاء حساب',
                            style: TextStyle(
                              color: Colors.white,
                              fontSize: 18,
                              fontFamily: 'Inter',
                              fontWeight: FontWeight.w800,
                            ),
                          ),
                        ),
                      ),
                    ),

                    // Back to Login Link
                    Positioned(
                      left: 0,
                      right: 0,
                      top: 655,
                      child: Row(
                        mainAxisAlignment: MainAxisAlignment.center,
                        children: [
                          GestureDetector(
                            onTap: () => Navigator.of(context).pop(),
                            child: const Text(
