// New Booking Page (Iphone1617Pro2)
class Iphone1617Pro2 extends StatefulWidget {
  const Iphone1617Pro2({super.key});

  @override
  State<Iphone1617Pro2> createState() => _Iphone1617Pro2State();
}

class _Iphone1617Pro2State extends State<Iphone1617Pro2> {
  final TextEditingController _cementTypeController = TextEditingController(text: 'اسمنت اكياس');
  final TextEditingController _quantityController = TextEditingController(text: '30');
  final TextEditingController _dateTimeController = TextEditingController();
  final TextEditingController _plateNumberController = TextEditingController(text: 'ABC 1234');
  final TextEditingController _driverNameController = TextEditingController(text: 'مجيب قادر');
  final TextEditingController _driverPhoneController = TextEditingController();
  final TextEditingController _locationController = TextEditingController(text: 'حائل - النقرة');

  bool _saving = false;
  DateTime _date = DateTime.now().add(const Duration(days: 1));
  TimeOfDay _time = const TimeOfDay(hour: 9, minute: 0);

  static const _months = [
    'يناير', 'فبراير', 'مارس', 'أبريل', 'مايو', 'يونيو',
    'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر'
  ];

  @override
  void initState() {
    super.initState();
    _refreshDateText();
  }

  void _refreshDateText() {
    final h12 = _time.hourOfPeriod == 0 ? 12 : _time.hourOfPeriod;
    final m = _time.minute == 0 ? '' : ':${_time.minute.toString().padLeft(2, '0')}';
    final ap = _time.period == DayPeriod.am ? 'ص' : 'م';
    _dateTimeController.text = '${_date.day} ${_months[_date.month - 1]} . $h12$m $ap';
  }

  Future<void> _pickDateTime() async {
    final d = await showDatePicker(
      context: context,
      initialDate: _date,
      firstDate: DateTime.now(),
      lastDate: DateTime.now().add(const Duration(days: 365)),
    );
    if (d == null || !mounted) return;
    final t = await showTimePicker(context: context, initialTime: _time);
    setState(() {
      _date = d;
      if (t != null) _time = t;
      _refreshDateText();
    });
  }

  Future<void> _confirm() async {
    final qty = double.tryParse(_quantityController.text.trim()) ?? 0;
    String? opt(TextEditingController c) => c.text.trim().isEmpty ? null : c.text.trim();
    final phone = _driverPhoneController.text.trim();
    setState(() => _saving = true);
    try {
      final hh = _time.hour.toString().padLeft(2, '0');
      final mm = _time.minute.toString().padLeft(2, '0');
      final b = await ApiService.createBooking(
        cementType: _cementTypeController.text.trim(),
        quantityTon: qty,
        bookingDate: _date,
        bookingTime: '$hh:$mm:00',
        driverName: opt(_driverNameController),
        plateNumber: opt(_plateNumberController),
        driverMobile: RegExp(r'^05\d{8}$').hasMatch(phone) ? phone : null,
        deliveryLocation: opt(_locationController),
      );
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('تم الحجز بنجاح: ${b.code}')),
      );
      Navigator.of(context).pushReplacement(
        MaterialPageRoute(builder: (context) => const Iphone1617Pro10()),
      );
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(e.toString())));
    } finally {
      if (mounted) setState(() => _saving = false);
    }
  }

  @override
  void dispose() {
    _cementTypeController.dispose();
    _quantityController.dispose();
    _dateTimeController.dispose();
    _plateNumberController.dispose();
    _driverNameController.dispose();
    _driverPhoneController.dispose();
    _locationController.dispose();
    super.dispose();
  }

