class Iphone1617Pro11 extends StatelessWidget {
  const Iphone1617Pro11({super.key});

  @override
  Widget build(BuildContext context) {
    return const Iphone1617Pro10(initialFilter: 1);
  }
}

class _Iphone1617Pro10State extends State<Iphone1617Pro10> {
  late int _selectedFilter; // 0: الكل, 1: نشطة, 2: مكتملة
  List<Booking>? _items;
  String? _error;
  bool _loadingList = true;

  static const _months = [
    'يناير', 'فبراير', 'مارس', 'أبريل', 'مايو', 'يونيو',
    'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر'
  ];

  @override
  void initState() {
    super.initState();
    _selectedFilter = widget.initialFilter;
    _load();
  }

  Future<void> _load() async {
    setState(() {
      _loadingList = true;
      _error = null;
    });
    try {
      final f = _selectedFilter == 1 ? 'active' : _selectedFilter == 2 ? 'completed' : 'all';
      final list = await ApiService.getBookings(filter: f);
      if (!mounted) return;
      setState(() {
        _items = list;
        _loadingList = false;
      });
    } catch (e) {
      if (!mounted) return;
      setState(() {
        _error = e.toString();
        _loadingList = false;
      });
    }
  }

  (String, Color) _statusInfo(String s) {
    switch (s) {
      case 'Loading':
        return ('جاري التحميل', const Color(0xFF0B7856));
      case 'Completed':
        return ('مكتمل', const Color(0xFFB8B0AE));
      default:
        return ('بانتظار التاكيد', const Color(0xFFD08C0B));
    }
  }

  Widget _buildBookingsList() {
    if (_loadingList) {
      return const Center(child: CircularProgressIndicator());
    }
    if (_error != null) {
      return Center(
        child: Text(_error!, textAlign: TextAlign.center, style: const TextStyle(color: Colors.white)),
      );
    }
    final items = _items ?? [];
    if (items.isEmpty) {
      return const Center(
        child: Text('لا توجد حجوزات', style: TextStyle(color: Colors.white, fontSize: 18, fontFamily: 'Inter')),
      );
    }
    return RefreshIndicator(
      onRefresh: _load,
      child: ListView.separated(
        padding: EdgeInsets.zero,
        itemCount: items.length,
        separatorBuilder: (_, index) => const SizedBox(height: 16),
        itemBuilder: (context, i) {
          final b = items[i];
          final (label, color) = _statusInfo(b.status);
          return GestureDetector(
            onTap: () => Navigator.of(context).push(
              MaterialPageRoute(builder: (context) => const Iphone1617Pro3()),
            ),
            child: Container(
              height: 106,
              padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
              decoration: ShapeDecoration(
                color: const Color(0xFF18212C),
                shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
              ),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.end,
                mainAxisAlignment: MainAxisAlignment.center,
                children: [
                  Row(
                    textDirection: TextDirection.rtl,
                    mainAxisAlignment: MainAxisAlignment.spaceBetween,
                    children: [
                      Text('#${b.code}',
                          style: const TextStyle(
                              color: Colors.white, fontSize: 24, fontFamily: 'Inter', fontWeight: FontWeight.w700)),
                      Container(
                        padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 6),
                        decoration: BoxDecoration(color: color, borderRadius: BorderRadius.circular(20)),
                        child: Text(label,
                            style: const TextStyle(
                                color: Colors.white, fontSize: 13, fontFamily: 'Inter', fontWeight: FontWeight.w700)),
                      ),
                    ],
                  ),
                  const SizedBox(height: 6),
                  Text('${b.cementType} . ${b.quantityTon.toStringAsFixed(0)} طن',
                      textDirection: TextDirection.rtl,
                      style: const TextStyle(color: Colors.white, fontSize: 14, fontFamily: 'Inter')),
                  const SizedBox(height: 4),
                  Text('${b.date.day} ${_months[b.date.month - 1]}',
                      textDirection: TextDirection.rtl,
                      style: const TextStyle(color: Colors.white, fontSize: 14, fontFamily: 'Inter')),
                ],
              ),
            ),
          );
        },
      ),
    );
  }

